LESSON_JSON = "{\n \"id\": \"nonparamt8\",\n \"topicId\": \"nonparam-t8\",\n \"moduleId\": \"nonparam\",\n \"title\": \"Linear rank tests for location and scale\",\n \"breadcrumb\": \"Non-parametric methods → Linear rank tests → Location and scale\",\n \"engine\": \"B\",\n \"engineName\": \"Choose scores to match location or scale.\",\n \"version\": \"1.0\",\n \"status\": \"approved\",\n \"estMin\": 96,\n \"objectives\": [\n  \"Define a linear rank statistic using scores assigned to pooled ranks.\",\n  \"Relate Wilcoxon rank-sum scores to the Mann–Whitney U statistic.\",\n  \"Recognise alternative location score systems.\",\n  \"Distinguish Ansari–Bradley and Mood scale score patterns.\",\n  \"Select a location or scale test and state its assumptions and direction.\"\n ],\n \"prereq\": [\n  {\n   \"id\": \"p1\",\n   \"name\": \"Pooled ranks and rank sums\",\n   \"why\": \"Linear rank statistics are formed from ranks in the combined sample.\"\n  },\n  {\n   \"id\": \"p2\",\n   \"name\": \"Location and scale\",\n   \"why\": \"The alternative determines whether scores should respond to ordering or dispersion.\"\n  },\n  {\n   \"id\": \"p3\",\n   \"name\": \"Two-independent-sample design\",\n   \"why\": \"The standard two-sample linear rank framework assumes independent samples.\"\n  }\n ],\n \"traps\": [\n  \"A linear rank statistic is T=Σa(Rᵢ); the score function matters.\",\n  \"Wilcoxon rank sum uses a(r)=r; U subtracts n₁(n₁+1)/2.\",\n  \"Ansari–Bradley scores are high near the pooled centre.\",\n  \"Mood scores are high at the pooled extremes.\",\n  \"A scale test is not automatically a test of variance without its centre assumptions.\",\n  \"Interpret a large statistic using the score direction and sample label.\"\n ],\n \"howto\": \"First identify whether the alternative is location or scale. For location, ordinary rank scores increase with rank. For scale, use a score pattern sensitive to centre or tails. State which sample's scores are being added and what a large total means.\",\n \"revision\": {\n  \"sheet\": [\n   \"General linear rank statistic: T=Σa(Rᵢ).\",\n   \"Wilcoxon rank sum: a(r)=r; T=R₁.\",\n   \"Mann–Whitney: U₁=R₁−n₁(n₁+1)/2.\",\n   \"Normal scores (van der Waerden) and Savage scores are alternative location score systems.\",\n   \"Ansari–Bradley: a(r)=min(r,N+1−r), high near centre.\",\n   \"Mood: a(r)=[r−(N+1)/2]², high at extremes.\",\n   \"Siegel–Tukey ranks from extremes inward for scale comparisons.\",\n   \"Fligner–Killeen ranks absolute deviations from group medians.\",\n   \"Location interpretation of rank-sum is clearest for similarly shaped distributions.\",\n   \"Scale procedures require attention to common centres, symmetry and centring assumptions.\"\n  ],\n  \"cards\": [\n   [\n    \"Linear rank statistic\",\n    \"T=Σa(Rᵢ)\"\n   ],\n   [\n    \"Wilcoxon score\",\n    \"a(r)=r\"\n   ],\n   [\n    \"Mann–Whitney\",\n    \"R₁−n₁(n₁+1)/2\"\n   ],\n   [\n    \"Ansari–Bradley\",\n    \"min(r,N+1−r), centre-high\"\n   ],\n   [\n    \"Mood\",\n    \"[r−(N+1)/2]², tail-high\"\n   ],\n   [\n    \"Siegel–Tukey\",\n    \"Extreme-inward ranks\"\n   ],\n   [\n    \"Fligner–Killeen\",\n    \"Ranks of absolute deviations\"\n   ],\n   [\n    \"First decision\",\n    \"Location or scale?\"\n   ]\n  ],\n  \"tricks\": [\n   \"Ordinary ranks rise with value: location.\",\n   \"Ansari–Bradley rises toward the centre: concentration.\",\n   \"Mood rises toward the tails: dispersion.\"\n  ],\n  \"shortcuts\": [\n   \"Wilcoxon scores = pooled ranks.\",\n   \"Ansari–Bradley = centre scores.\",\n   \"Mood = squared distance from rank centre.\"\n  ],\n  \"remember\": [\n   \"Score function must match the alternative.\",\n   \"Always state which sample's score total is being interpreted.\"\n  ]\n },\n \"refs\": [\n  {\n   \"title\": \"Nonparametric Statistical Methods\",\n   \"where\": \"Choosing rank-based procedures\",\n   \"site\": \"Hollander, Wolfe and Chicken\",\n   \"url\": \"\",\n   \"type\": \"Textbook\",\n   \"free\": false,\n   \"checked\": \"2026-11-12\",\n   \"why\": \"Standard reference for nonparametric test assumptions and selection.\"\n  },\n  {\n   \"title\": \"NIST/SEMATECH e-Handbook of Statistical Methods\",\n   \"where\": \"Nonparametric methods\",\n   \"site\": \"NIST\",\n   \"url\": \"https://www.itl.nist.gov/div898/handbook/\",\n   \"type\": \"Free online textbook\",\n   \"free\": true,\n   \"checked\": \"2026-11-12\",\n   \"why\": \"Reference for distributional and rank-based tests.\"\n  },\n  {\n   \"title\": \"Penn State STAT 415\",\n   \"where\": \"Nonparametric tests\",\n   \"site\": \"Penn State\",\n   \"url\": \"https://online.stat.psu.edu/stat415/\",\n   \"type\": \"Free online textbook\",\n   \"free\": true,\n   \"checked\": \"2026-11-12\",\n   \"why\": \"Accessible test-selection explanations.\"\n  }\n ],\n \"mastery\": {\n  \"minQ\": 10,\n  \"pass\": 80,\n  \"draw\": 10,\n  \"fmtMin\": {\n   \"numeric\": 70,\n   \"multi\": 70\n  },\n  \"diffMix\": {\n   \"easy\": 3,\n   \"moderate\": 5,\n   \"hard\": 2\n  },\n  \"noHints\": true,\n  \"retestDays\": 7,\n  \"note\": \"Proposed platform settings, not an NTA rule. Overall 80%, with 70% floors on numerical and multi-statement items, answered without hints.\"\n },\n \"provenance\": \"June 2026 Q33/Q42 variants include Wilcoxon–Mann–Whitney location-test selection, rank-sum conversion, tie handling and ordinal-scale requirements. No direct June 2026 question on Ansari–Bradley or Mood scale scores was identified in the inspected nonparametric variants. Scale examples are constructed and numerically checked.\",\n \"scenes\": [\n  {\n   \"kind\": \"foundation\",\n   \"id\": \"s0\",\n   \"mins\": 7,\n   \"title\": \"Start with ranks and score functions\",\n   \"objective\": \"Understand how pooled ranks become a test statistic.\",\n   \"ask\": {\n    \"q\": \"What is a pooled rank?\",\n    \"nudge\": \"The position of an observation in the combined ordered sample.\"\n   },\n   \"body\": [\n    \"A rank test replaces observations with positions in an ordered list. A linear rank statistic assigns a score to each rank and adds the scores for one sample.\",\n    \"The score function is chosen for the scientific alternative. Scores that increase with rank target a location ordering; scores large near the centre or at the extremes can target scale.\"\n   ],\n   \"items\": [\n    {\n     \"ask\": \"Why pool observations from two independent samples before ranking?\",\n     \"recall\": \"To put both groups on one common ordering.\",\n     \"refresh\": [\n      \"A pooled ranking shows where every observation lies relative to observations from both groups. Ranking each sample separately would erase this cross-group ordering.\",\n      \"The combined ranks are the input to a two-sample rank-sum or linear-rank statistic.\"\n     ]\n    },\n    {\n     \"ask\": \"What is a location difference?\",\n     \"recall\": \"A shift in the typical position or centre of a distribution.\",\n     \"refresh\": [\n      \"A location alternative asks whether one population tends to produce larger or smaller observations than another.\",\n      \"A rank-sum score increasing with rank is sensitive to systematic ordering. A median interpretation is clearest when distribution shapes are comparable.\"\n     ]\n    },\n    {\n     \"ask\": \"What is a scale difference?\",\n     \"recall\": \"A difference in spread or variability around a centre.\",\n     \"refresh\": [\n      \"Two groups can have the same centre but different dispersion. One may be more concentrated and the other more spread out.\",\n      \"A scale test must use information about distance from the centre or extremeness, rather than simply asking which group has larger values.\"\n     ]\n    }\n   ]\n  },\n  {\n   \"kind\": \"intuition\",\n   \"id\": \"s1\",\n   \"mins\": 7,\n   \"title\": \"Location and scale are different alternatives\",\n   \"objective\": \"See why the score pattern must match the question.\",\n   \"ask\": {\n    \"q\": \"If two groups share a centre but one is more dispersed, is this a location or scale question?\",\n    \"nudge\": \"It is a scale question.\"\n   },\n   \"body\": [\n    \"A location test asks whether observations from one group tend to be higher than observations from another. A scale test asks whether one group is more spread out around its centre.\",\n    \"A single rank score pattern cannot be optimal for every alternative. Linear rank methods make the score choice explicit.\"\n   ],\n   \"scenario\": {\n    \"teaser\": \"Two independent groups and a location alternative.\",\n    \"title\": \"Comparing typical outcomes\",\n    \"body\": [\n     \"A researcher compares an outcome from two independent groups. The question is whether one group tends to have larger values, which is a location question. A linear rank statistic assigns a score to each pooled rank and adds the scores belonging to one group. Choosing ordinary rank scores gives the Wilcoxon rank-sum statistic, which is equivalent to Mann–Whitney U after subtracting a fixed minimum rank sum. Other score systems, such as normal scores, target different location alternatives.\"\n    ],\n    \"q\": \"What does the ordinary Wilcoxon rank-sum score do?\",\n    \"answer\": \"It assigns increasing scores to pooled ranks and sums the ranks belonging to one group.\"\n   }\n  },\n  {\n   \"kind\": \"explore\",\n   \"id\": \"s2\",\n   \"mins\": 6,\n   \"title\": \"Look at three score patterns\",\n   \"objective\": \"Compare location scores with scale scores.\",\n   \"ask\": {\n    \"q\": \"Which ranks receive larger Ansari–Bradley scores?\",\n    \"nudge\": \"Ranks near the centre of the pooled ordering.\"\n   },\n   \"viz\": {\n    \"type\": \"rank-null\",\n    \"caption\": \"Location scores rise with rank; scale scores can be largest at the centre or at the extremes.\"\n   },\n   \"body\": [\n    \"For N=8, ordinary Wilcoxon scores are 1,2,3,4,5,6,7,8. Ansari–Bradley scores are 1,2,3,4,4,3,2,1, largest near the centre.\",\n    \"Mood scores are squared distances from the pooled centre (N+1)/2. They are largest at the extremes.\"\n   ]\n  },\n  {\n   \"kind\": \"theory\",\n   \"id\": \"s3\",\n   \"mins\": 9,\n   \"title\": \"Linear rank statistics for location\",\n   \"objective\": \"Define the general statistic and the Wilcoxon score choice.\",\n   \"ask\": {\n    \"q\": \"What score function gives the Wilcoxon rank-sum statistic?\",\n    \"nudge\": \"a(r)=r, the pooled rank itself.\"\n   },\n   \"blocks\": [\n    {\n     \"t\": \"formula\",\n     \"h\": \"General linear rank statistic\",\n     \"body\": \"T=Σᵢ₌₁ⁿ¹ a(Rᵢ), where Rᵢ is a pooled rank and a(r) is the selected score function.\"\n    },\n    {\n     \"t\": \"formula\",\n     \"h\": \"Wilcoxon rank-sum\",\n     \"body\": \"Choose a(r)=r. Then T=R₁, the pooled rank sum for sample 1. Mann–Whitney U₁=R₁−n₁(n₁+1)/2.\"\n    },\n    {\n     \"t\": \"def\",\n     \"h\": \"Other location scores\",\n     \"body\": \"Normal scores (van der Waerden) and Savage scores transform rank positions differently and are selected for particular location alternatives.\"\n    },\n    {\n     \"t\": \"step\",\n     \"h\": \"Interpretation\",\n     \"body\": \"A large rank-sum statistic indicates sample 1 tends to occupy higher pooled ranks. Direction depends on the sample label and score convention.\"\n    }\n   ],\n   \"flow\": {\n    \"title\": \"Choose the score family\",\n    \"alt\": \"A directional shift leads to increasing location scores; a spread difference leads to centre- or tail-sensitive scale scores.\",\n    \"nodes\": [\n     {\n      \"id\": \"a\",\n      \"r\": 0,\n      \"c\": 1,\n      \"label\": \"State alternative\",\n      \"kind\": \"start\"\n     },\n     {\n      \"id\": \"b\",\n      \"r\": 1,\n      \"c\": 0,\n      \"label\": \"Location shift\",\n      \"kind\": \"step\"\n     },\n     {\n      \"id\": \"c\",\n      \"r\": 1,\n      \"c\": 2,\n      \"label\": \"Scale difference\",\n      \"kind\": \"step\"\n     },\n     {\n      \"id\": \"d\",\n      \"r\": 2,\n      \"c\": 0,\n      \"label\": \"Wilcoxon / normal scores\",\n      \"kind\": \"step\"\n     },\n     {\n      \"id\": \"e\",\n      \"r\": 2,\n      \"c\": 2,\n      \"label\": \"Ansari–Bradley / Mood\",\n      \"kind\": \"step\"\n     },\n     {\n      \"id\": \"f\",\n      \"r\": 3,\n      \"c\": 1,\n      \"label\": \"Check assumptions\",\n      \"kind\": \"end\"\n     }\n    ],\n    \"edges\": [\n     {\n      \"from\": \"a\",\n      \"to\": \"b\"\n     },\n     {\n      \"from\": \"a\",\n      \"to\": \"c\"\n     },\n     {\n      \"from\": \"b\",\n      \"to\": \"d\"\n     },\n     {\n      \"from\": \"c\",\n      \"to\": \"e\"\n     },\n     {\n      \"from\": \"d\",\n      \"to\": \"f\"\n     },\n     {\n      \"from\": \"e\",\n      \"to\": \"f\"\n     }\n    ],\n    \"note\": \"The score function must match the alternative.\"\n   }\n  },\n  {\n   \"kind\": \"worked\",\n   \"id\": \"s4\",\n   \"mins\": 10,\n   \"title\": \"Worked example: rank sum to U\",\n   \"objective\": \"Convert a linear rank statistic into Mann–Whitney U.\",\n   \"ask\": {\n    \"q\": \"Why subtract n₁(n₁+1)/2 from R₁?\",\n    \"nudge\": \"It is the minimum possible rank sum for n₁ observations.\"\n   },\n   \"problem\": \"A sample of size n₁=5 has pooled rank sum R₁=28. Calculate U₁.\",\n   \"steps\": [\n    {\n     \"say\": \"Identify the linear rank score.\",\n     \"math\": \"a(r)=r; T=R₁=28\",\n     \"why\": \"Wilcoxon rank-sum uses pooled ranks as scores.\"\n    },\n    {\n     \"say\": \"Calculate the minimum rank sum.\",\n     \"math\": \"5×6/2=15\",\n     \"why\": \"The first five ranks sum to 15.\"\n    },\n    {\n     \"say\": \"Convert to U.\",\n     \"math\": \"U₁=28−15=13\",\n     \"why\": \"Subtracting the minimum rank sum gives the Mann–Whitney form.\"\n    },\n    {\n     \"say\": \"Check the interpretation.\",\n     \"math\": \"U₁+U₂=n₁n₂\",\n     \"why\": \"The two U statistics add to the product of sample sizes.\"\n    }\n   ],\n   \"after\": \"The rank sum is 28; the Mann–Whitney statistic is 13. Do not report R₁ as U₁.\"\n  },\n  {\n   \"kind\": \"recall\",\n   \"id\": \"s5\",\n   \"mins\": 3,\n   \"title\": \"Pause and retrieve\",\n   \"objective\": \"Recall the central matching rules.\",\n   \"intro\": \"Answer before revealing.\",\n   \"items\": [\n    {\n     \"q\": \"General linear rank statistic?\",\n     \"a\": \"T=Σa(Rᵢ).\"\n    },\n    {\n     \"q\": \"Wilcoxon score a(r)?\",\n     \"a\": \"a(r)=r.\"\n    },\n    {\n     \"q\": \"Mann–Whitney from rank sum?\",\n     \"a\": \"U₁=R₁−n₁(n₁+1)/2.\"\n    },\n    {\n     \"q\": \"Ansari–Bradley scores are largest where?\",\n     \"a\": \"Near the centre of pooled ranks.\"\n    },\n    {\n     \"q\": \"Mood scale scores are largest where?\",\n     \"a\": \"At the extremes, far from the pooled centre.\"\n    }\n   ]\n  },\n  {\n   \"kind\": \"completion\",\n   \"id\": \"s6\",\n   \"mins\": 8,\n   \"title\": \"Complete the test-selection grid\",\n   \"objective\": \"Fill the missing procedure from the design.\",\n   \"problem\": \"For n₁=4 and pooled rank sum R₁=22, find U₁.\",\n   \"steps\": [\n    {\n     \"say\": \"Find the minimum rank sum.\",\n     \"blank\": {\n      \"prompt\": \"4×5/2=…\",\n      \"answer\": \"10\",\n      \"accept\": [\n       \"10.0\"\n      ],\n      \"hint\": \"Use n₁(n₁+1)/2.\"\n     },\n     \"why\": \"The smallest four ranks sum to 10.\"\n    },\n    {\n     \"say\": \"Subtract from R₁.\",\n     \"blank\": {\n      \"prompt\": \"U₁=22−10=…\",\n      \"answer\": \"12\",\n      \"accept\": [\n       \"12.0\"\n      ],\n      \"hint\": \"Subtract the minimum possible rank sum.\"\n     },\n     \"why\": \"This is the Mann–Whitney form of the rank-sum statistic.\"\n    },\n    {\n     \"say\": \"State the test direction.\",\n     \"blank\": {\n      \"prompt\": \"A larger R₁ means sample 1 tends to occupy … pooled ranks.\",\n      \"answer\": \"higher\",\n      \"accept\": [\n       \"larger\"\n      ],\n      \"hint\": \"Wilcoxon scores increase with rank.\"\n     },\n     \"why\": \"Increasing scores give greater weight to observations at higher pooled positions.\"\n    }\n   ],\n   \"after\": \"The score function determines what a large statistic means.\",\n   \"ask\": {\n    \"q\": \"Which minimum rank sum is subtracted from R₁ to obtain U₁?\",\n    \"nudge\": \"n₁(n₁+1)/2.\"\n   }\n  },\n  {\n   \"kind\": \"theory\",\n   \"id\": \"s7\",\n   \"mins\": 8,\n   \"title\": \"Linear rank tests for scale\",\n   \"objective\": \"Compare centre-sensitive and tail-sensitive scores.\",\n   \"ask\": {\n    \"q\": \"Which score pattern gives high scores near the pooled centre?\",\n    \"nudge\": \"Ansari–Bradley.\"\n   },\n   \"blocks\": [\n    {\n     \"t\": \"formula\",\n     \"h\": \"Ansari–Bradley\",\n     \"body\": \"For N pooled ranks, a(r)=min(r,N+1−r). Scores are small at both extremes and large near the centre. A more concentrated sample tends to receive a larger score sum.\"\n    },\n    {\n     \"t\": \"formula\",\n     \"h\": \"Mood scale scores\",\n     \"body\": \"A(r)=[r−(N+1)/2]². Scores are largest at the extremes and smallest near the centre. A more dispersed sample tends to accumulate larger Mood scores.\"\n    },\n    {\n     \"t\": \"def\",\n     \"h\": \"Siegel–Tukey and Fligner–Killeen\",\n     \"body\": \"Siegel–Tukey assigns ranks from the extremes inward to compare scale. Fligner–Killeen ranks absolute deviations from group medians for a robust scale comparison.\"\n    },\n    {\n     \"t\": \"step\",\n     \"h\": \"Assumption caution\",\n     \"body\": \"Scale tests generally require comparable centres or a suitable centring step. Check each procedure's symmetry and sampling assumptions before interpreting it as a pure variance test.\"\n    }\n   ]\n  },\n  {\n   \"kind\": \"guided\",\n   \"id\": \"s8\",\n   \"mins\": 8,\n   \"title\": \"Guided calculation: scale scores\",\n   \"objective\": \"Calculate Ansari–Bradley score totals.\",\n   \"problem\": \"For N=8, Ansari–Bradley scores are 1,2,3,4,4,3,2,1. Sample A occupies ranks 1,2,7,8. Find its score sum.\",\n   \"hints\": [\n    \"Read the score for each pooled rank.\",\n    \"Select the four scores for ranks 1,2,7,8.\",\n    \"Add them and compare with the centre ranks.\"\n   ],\n   \"answer\": \"The scores are 1, 2, 2 and 1, so the Ansari–Bradley total is 6.\",\n   \"check\": \"The centre ranks receive larger scores; an extreme-rank sample should have a smaller total.\",\n   \"solution\": [\n    {\n     \"say\": \"Read the four scores.\",\n     \"math\": \"a(1)=1; a(2)=2; a(7)=2; a(8)=1\",\n     \"why\": \"The score function is symmetric around the pooled centre.\"\n    },\n    {\n     \"say\": \"Add the scores.\",\n     \"math\": \"T_A=1+2+2+1=6\",\n     \"why\": \"This is the score sum for sample A.\"\n    },\n    {\n     \"say\": \"Compare central ranks.\",\n     \"math\": \"Ranks 3,4,5,6 receive 3,4,4,3; total=14\",\n     \"why\": \"Ansari–Bradley scores are largest near the centre.\"\n    }\n   ],\n   \"scenario\": {\n    \"teaser\": \"Two production lines have similar centres but possibly different spread.\",\n    \"title\": \"Comparing process variability\",\n    \"body\": [\n     \"A quality team compares variability in two independent production lines. The group centres are similar, but one line may have more spread. A scale test should respond to how far observations lie from the centre, not simply whether one group has larger values. Ansari–Bradley gives larger scores to central pooled ranks, while Mood's scale test gives larger scores to ranks far from the pooled centre. The score pattern must match the alternative being tested.\"\n    ],\n    \"q\": \"Which score family gives high scores to central pooled ranks?\",\n    \"answer\": \"Ansari–Bradley scores.\"\n   },\n   \"ask\": {\n    \"q\": \"What does a larger Ansari–Bradley score sum indicate under a common-centre scale alternative?\",\n    \"nudge\": \"A more concentrated sample.\"\n   }\n  },\n  {\n   \"kind\": \"trapcheck\",\n   \"id\": \"s9\",\n   \"mins\": 6,\n   \"title\": \"Six statements to challenge\",\n   \"objective\": \"Detect common test-selection errors.\",\n   \"intro\": \"Mark each claim true or false before revealing the reason.\",\n   \"items\": [\n    {\n     \"claim\": \"A linear rank statistic sums scores assigned to pooled ranks.\",\n     \"tf\": true,\n     \"why\": \"True. T=Σa(Rᵢ) for the observations in the selected sample.\"\n    },\n    {\n     \"claim\": \"Wilcoxon rank-sum uses a(r)=r.\",\n     \"tf\": true,\n     \"why\": \"True. The score is the pooled rank itself.\"\n    },\n    {\n     \"claim\": \"Mann–Whitney U equals the Wilcoxon rank sum R₁.\",\n     \"tf\": false,\n     \"why\": \"False. U₁=R₁−n₁(n₁+1)/2.\"\n    },\n    {\n     \"claim\": \"Ansari–Bradley scores are largest near the pooled centre.\",\n     \"tf\": true,\n     \"why\": \"True. The score min(r,N+1−r) is centre-sensitive.\"\n    },\n    {\n     \"claim\": \"Mood scale scores are largest at the extremes.\",\n     \"tf\": true,\n     \"why\": \"True. Mood uses squared distance from the pooled rank centre.\"\n    },\n    {\n     \"claim\": \"A scale test can always be interpreted as a pure variance test without checking centre assumptions.\",\n     \"tf\": false,\n     \"why\": \"False. Scale-test interpretation depends on centring and shape assumptions.\"\n    }\n   ]\n  },\n  {\n   \"kind\": \"guided\",\n   \"id\": \"s10\",\n   \"mins\": 8,\n   \"title\": \"Guided calculation: a quick numeric check\",\n   \"objective\": \"Calculate a statistic only after identifying its test.\",\n   \"problem\": \"Study A asks whether one independent group tends to have larger values than another. Study B asks whether two groups with similar centres differ in spread. Which score family is appropriate for each?\",\n   \"hints\": [\n    \"Study A is a location alternative.\",\n    \"Study B is a scale alternative.\",\n    \"Choose increasing rank scores for location and centre/tail-sensitive scores for scale.\"\n   ],\n   \"answer\": \"Study A: Wilcoxon rank-sum/Mann–Whitney or another location score system. Study B: Ansari–Bradley or Mood, with assumptions checked.\",\n   \"check\": \"Do not choose a location rank-sum solely because it is familiar when the target is spread.\",\n   \"solution\": [\n    {\n     \"say\": \"Identify Study A.\",\n     \"math\": \"Larger values → location\",\n     \"why\": \"The alternative is directional ordering in pooled ranks.\"\n    },\n    {\n     \"say\": \"Choose location scores.\",\n     \"math\": \"Wilcoxon rank-sum: a(r)=r\",\n     \"why\": \"Scores increase with pooled rank.\"\n    },\n    {\n     \"say\": \"Identify Study B.\",\n     \"math\": \"Similar centres, different spread → scale\",\n     \"why\": \"The test must respond to distance from the centre or extremeness.\"\n    },\n    {\n     \"say\": \"Choose scale scores.\",\n     \"math\": \"Ansari–Bradley or Mood\",\n     \"why\": \"Their scores target dispersion rather than a simple location shift.\"\n    }\n   ],\n   \"ask\": {\n    \"q\": \"Which score pattern is appropriate when the target is spread rather than location?\",\n    \"nudge\": \"A scale-oriented score such as Ansari–Bradley or Mood.\"\n   }\n  },\n  {\n   \"kind\": \"theory\",\n   \"id\": \"s11\",\n   \"mins\": 6,\n   \"title\": \"Assumptions and interpretation\",\n   \"objective\": \"State what a rank-score result can support.\",\n   \"ask\": {\n    \"q\": \"Why check score direction before interpreting a large statistic?\",\n    \"nudge\": \"The score function and sample label determine which alternative produces a large value.\"\n   },\n   \"blocks\": [\n    {\n     \"t\": \"def\",\n     \"h\": \"Location interpretation\",\n     \"body\": \"Wilcoxon–Mann–Whitney compares independent distributions through pooled ordering. A simple median-shift interpretation is strongest when distributions have similar shapes.\"\n    },\n    {\n     \"t\": \"def\",\n     \"h\": \"Scale interpretation\",\n     \"body\": \"Ansari–Bradley and Mood target spread differences under their stated conditions. Check whether groups share a centre or whether the procedure uses a suitable centring step.\"\n    },\n    {\n     \"t\": \"step\",\n     \"h\": \"Exam response structure\",\n     \"body\": \"Name the target (location or scale), state the design (independent or paired), identify the score pattern, and explain what a large statistic means for the labelled sample.\"\n    }\n   ]\n  },\n  {\n   \"kind\": \"recall\",\n   \"id\": \"s12\",\n   \"mins\": 3,\n   \"title\": \"Second recall\",\n   \"objective\": \"Retrieve the full test map.\",\n   \"intro\": \"Answer, then reveal.\",\n   \"items\": [\n    {\n     \"q\": \"Wilcoxon rank score?\",\n     \"a\": \"a(r)=r.\"\n    },\n    {\n     \"q\": \"U from R₁?\",\n     \"a\": \"R₁−n₁(n₁+1)/2.\"\n    },\n    {\n     \"q\": \"Ansari–Bradley score?\",\n     \"a\": \"min(r,N+1−r).\"\n    },\n    {\n     \"q\": \"Mood score?\",\n     \"a\": \"[r−(N+1)/2]².\"\n    },\n    {\n     \"q\": \"What is the first decision?\",\n     \"a\": \"Whether the alternative concerns location or scale.\"\n    }\n   ]\n  },\n  {\n   \"kind\": \"summary\",\n   \"id\": \"s13\",\n   \"mins\": 3,\n   \"title\": \"What you should now be able to do\",\n   \"objective\": \"Select the test from design and target.\",\n   \"body\": [\n    \"Define a linear rank statistic as a sum of scores assigned to pooled ranks.\",\n    \"Use ordinary increasing scores for Wilcoxon rank-sum and convert R₁ to Mann–Whitney U.\",\n    \"Recognise Ansari–Bradley centre-sensitive scores and Mood tail-sensitive scores.\",\n    \"Identify Siegel–Tukey and Fligner–Killeen as scale-oriented rank procedures.\",\n    \"State design, score direction and assumptions before interpreting a statistic.\"\n   ],\n   \"ask\": {\n    \"q\": \"What should be identified before interpreting a linear rank statistic?\",\n    \"nudge\": \"The alternative, score function and sample label.\"\n   }\n  },\n  {\n   \"kind\": \"quiz\",\n   \"id\": \"s14\",\n   \"mins\": 4,\n   \"title\": \"Mastery test\",\n   \"objective\": \"Demonstrate accurate test selection on mixed designs.\",\n   \"setId\": \"nonparam_t8_mastery\"\n  }\n ]\n}"
POOL_JSON = "{\n \"moduleId\": \"nonparam\",\n \"topicId\": \"nonparam-t8\",\n \"source\": \"mastery\",\n \"label\": \"Linear rank tests for location and scale — mastery test\",\n \"count\": 20,\n \"items\": [\n  {\n   \"id\": \"np-t8-m-01\",\n   \"format\": \"single\",\n   \"diff\": \"easy\",\n   \"topic\": \"nonparam-t8\",\n   \"stem\": \"A linear rank statistic has the general form:\",\n   \"options\": [\n    \"Σa(Rᵢ)\",\n    \"ΣXᵢ²\",\n    \"ΣRᵢ/n\",\n    \"max(Rᵢ)\"\n   ],\n   \"answer\": \"A\",\n   \"explanation\": \"A linear rank statistic assigns a score a(Rᵢ) to each pooled rank and sums those scores for the selected sample.\"\n  },\n  {\n   \"id\": \"np-t8-m-02\",\n   \"format\": \"single\",\n   \"diff\": \"easy\",\n   \"topic\": \"nonparam-t8\",\n   \"stem\": \"The Wilcoxon rank-sum score function is:\",\n   \"options\": [\n    \"a(r)=r²\",\n    \"a(r)=r\",\n    \"a(r)=1/r\",\n    \"a(r)=0\"\n   ],\n   \"answer\": \"B\",\n   \"explanation\": \"Wilcoxon rank-sum uses the pooled rank itself as its score, so a(r)=r.\"\n  },\n  {\n   \"id\": \"np-t8-m-03\",\n   \"format\": \"single\",\n   \"diff\": \"easy\",\n   \"topic\": \"nonparam-t8\",\n   \"stem\": \"The Mann–Whitney statistic from rank sum R₁ is:\",\n   \"options\": [\n    \"R₁+n₁(n₁+1)/2\",\n    \"R₁/n₁\",\n    \"R₁−n₁(n₁+1)/2\",\n    \"n₁n₂−R₁\"\n   ],\n   \"answer\": \"C\",\n   \"explanation\": \"Subtract the minimum possible rank sum n₁(n₁+1)/2 from R₁ to obtain U₁.\"\n  },\n  {\n   \"id\": \"np-t8-m-04\",\n   \"format\": \"single\",\n   \"diff\": \"easy\",\n   \"topic\": \"nonparam-t8\",\n   \"stem\": \"Ansari–Bradley scores are largest for ranks:\",\n   \"options\": [\n    \"At the extremes\",\n    \"Equal to zero\",\n    \"Only in sample 1\",\n    \"Near the pooled centre\"\n   ],\n   \"answer\": \"D\",\n   \"explanation\": \"The score min(r,N+1−r) is symmetric and largest near the centre of the pooled ranking.\"\n  },\n  {\n   \"id\": \"np-t8-m-05\",\n   \"format\": \"single\",\n   \"diff\": \"easy\",\n   \"topic\": \"nonparam-t8\",\n   \"stem\": \"Mood's scale scores are based on:\",\n   \"options\": [\n    \"The squared distance from the pooled rank centre\",\n    \"The raw sample mean\",\n    \"The sign of paired differences\",\n    \"The number of runs\"\n   ],\n   \"answer\": \"A\",\n   \"explanation\": \"Mood uses squared deviations of ranks from (N+1)/2, giving high scores to extreme ranks.\"\n  },\n  {\n   \"id\": \"np-t8-m-06\",\n   \"format\": \"single\",\n   \"diff\": \"easy\",\n   \"topic\": \"nonparam-t8\",\n   \"stem\": \"A test designed to detect differences in spread is a:\",\n   \"options\": [\n    \"Location test\",\n    \"Scale test\",\n    \"Correlation test\",\n    \"Goodness-of-fit test\"\n   ],\n   \"answer\": \"B\",\n   \"explanation\": \"A scale test targets dispersion around a centre, rather than a systematic shift in typical values.\"\n  },\n  {\n   \"id\": \"np-t8-m-07\",\n   \"format\": \"numeric\",\n   \"diff\": \"moderate\",\n   \"topic\": \"nonparam-t8\",\n   \"stem\": \"For n₁=5 and R₁=28, the Mann–Whitney U₁ is:\",\n   \"options\": [\n    \"10\",\n    \"12\",\n    \"13\",\n    \"15\"\n   ],\n   \"answer\": \"C\",\n   \"explanation\": \"U₁=28−5×6/2=28−15=13. The rank sum and U statistic are different quantities.\",\n   \"check\": \"Computed check: 13.\"\n  },\n  {\n   \"id\": \"np-t8-m-08\",\n   \"format\": \"numeric\",\n   \"diff\": \"moderate\",\n   \"topic\": \"nonparam-t8\",\n   \"stem\": \"For N=8, Ansari–Bradley scores are 1,2,3,4,4,3,2,1. The score sum for ranks 1,2,7,8 is:\",\n   \"options\": [\n    \"4\",\n    \"5\",\n    \"8\",\n    \"6\"\n   ],\n   \"answer\": \"D\",\n   \"explanation\": \"The scores are 1,2,2,1, which sum to 6. Extreme ranks receive lower Ansari–Bradley scores.\",\n   \"check\": \"Computed check: 6.\"\n  },\n  {\n   \"id\": \"np-t8-m-09\",\n   \"format\": \"numeric\",\n   \"diff\": \"moderate\",\n   \"topic\": \"nonparam-t8\",\n   \"stem\": \"For N=8, Mood scores are squared deviations from 4.5. The total score for ranks 1,2,7,8 is:\",\n   \"options\": [\n    \"37\",\n    \"30\",\n    \"25\",\n    \"42\"\n   ],\n   \"answer\": \"A\",\n   \"explanation\": \"Scores are 12.25, 6.25, 6.25 and 12.25; their sum is 37. The most extreme ranks receive the largest scores.\",\n   \"check\": \"Computed check: 37.\"\n  },\n  {\n   \"id\": \"np-t8-m-10\",\n   \"format\": \"single\",\n   \"diff\": \"moderate\",\n   \"topic\": \"nonparam-t8\",\n   \"stem\": \"Which score system is most directly associated with a location alternative?\",\n   \"options\": [\n    \"Squared distance from the rank centre\",\n    \"Increasing pooled rank scores\",\n    \"Centre-high Ansari–Bradley scores\",\n    \"Absolute deviations from group medians\"\n   ],\n   \"answer\": \"B\",\n   \"explanation\": \"Increasing rank scores give greater weight to observations that lie higher in the pooled ordering, targeting location.\"\n  },\n  {\n   \"id\": \"np-t8-m-11\",\n   \"format\": \"single\",\n   \"diff\": \"moderate\",\n   \"topic\": \"nonparam-t8\",\n   \"stem\": \"Which scale test uses scores min(r,N+1−r)?\",\n   \"options\": [\n    \"Mood\",\n    \"Mann–Whitney\",\n    \"Ansari–Bradley\",\n    \"Kruskal–Wallis\"\n   ],\n   \"answer\": \"C\",\n   \"explanation\": \"Ansari–Bradley uses symmetric scores that are largest near the centre of the pooled ranks.\"\n  },\n  {\n   \"id\": \"np-t8-m-12\",\n   \"format\": \"multi\",\n   \"diff\": \"moderate\",\n   \"topic\": \"nonparam-t8\",\n   \"stem\": \"Which statements are correct? A. Wilcoxon rank-sum uses a(r)=r. B. U₁ is R₁ minus the minimum rank sum. C. Ansari–Bradley scores are centre-high. D. Mood scores are largest at the centre.\",\n   \"options\": [\n    \"A, B, C and D\",\n    \"A and D only\",\n    \"B and D only\",\n    \"A, B and C only\"\n   ],\n   \"answer\": \"D\",\n   \"explanation\": \"A, B and C are correct. Mood scores are largest at the extremes because they square distance from the rank centre.\",\n   \"statements\": [\n    \"Wilcoxon rank-sum uses a(r)=r.\",\n    \"U₁ is R₁ minus the minimum rank sum.\",\n    \"Ansari–Bradley scores are centre-high.\",\n    \"Mood scores are largest at the centre.\"\n   ],\n   \"verdicts\": {\n    \"A\": {\n     \"tf\": true,\n     \"why\": \"True: ordinary Wilcoxon scores equal the pooled ranks.\"\n    },\n    \"B\": {\n     \"tf\": true,\n     \"why\": \"True: U₁=R₁−n₁(n₁+1)/2.\"\n    },\n    \"C\": {\n     \"tf\": true,\n     \"why\": \"True: Ansari–Bradley scores are largest near the pooled centre.\"\n    },\n    \"D\": {\n     \"tf\": false,\n     \"why\": \"False: Mood scores are largest at the extremes.\"\n    }\n   }\n  },\n  {\n   \"id\": \"np-t8-m-13\",\n   \"format\": \"single\",\n   \"diff\": \"moderate\",\n   \"topic\": \"nonparam-t8\",\n   \"stem\": \"Siegel–Tukey is primarily used as a rank procedure for:\",\n   \"options\": [\n    \"Scale difference\",\n    \"Location shift\",\n    \"Sequence randomness\",\n    \"One-sample CDF fit\"\n   ],\n   \"answer\": \"A\",\n   \"explanation\": \"Siegel–Tukey assigns ranks from the extremes inward to compare scale or dispersion between samples.\"\n  },\n  {\n   \"id\": \"np-t8-m-14\",\n   \"format\": \"numeric\",\n   \"diff\": \"moderate\",\n   \"topic\": \"nonparam-t8\",\n   \"stem\": \"For n₁=4 and R₁=22, the Mann–Whitney U₁ is:\",\n   \"options\": [\n    \"8\",\n    \"12\",\n    \"10\",\n    \"16\"\n   ],\n   \"answer\": \"B\",\n   \"explanation\": \"U₁=22−4×5/2=22−10=12. The minimum rank sum for four observations is 10.\",\n   \"check\": \"Computed check: 12.\"\n  },\n  {\n   \"id\": \"np-t8-m-15\",\n   \"format\": \"single\",\n   \"diff\": \"moderate\",\n   \"topic\": \"nonparam-t8\",\n   \"stem\": \"Fligner–Killeen is based on ranks of:\",\n   \"options\": [\n    \"Raw observations\",\n    \"Cumulative probabilities\",\n    \"Absolute deviations from group medians\",\n    \"Signs of paired differences\"\n   ],\n   \"answer\": \"C\",\n   \"explanation\": \"Fligner–Killeen centres observations by group medians and ranks absolute deviations to compare scale robustly.\"\n  },\n  {\n   \"id\": \"np-t8-m-16\",\n   \"format\": \"numeric\",\n   \"diff\": \"moderate\",\n   \"topic\": \"nonparam-t8\",\n   \"stem\": \"For N=8, the Mood score assigned to pooled rank 4 is:\",\n   \"options\": [\n    \"12.25\",\n    \"2.25\",\n    \"6.25\",\n    \"0.25\"\n   ],\n   \"answer\": \"D\",\n   \"explanation\": \"The rank centre is (8+1)/2=4.5. Mood score=(4−4.5)²=0.25.\",\n   \"check\": \"Computed check: 0.25.\"\n  },\n  {\n   \"id\": \"np-t8-m-17\",\n   \"format\": \"multi\",\n   \"diff\": \"hard\",\n   \"topic\": \"nonparam-t8\",\n   \"stem\": \"Which statements about scale tests are defensible? A. They target dispersion rather than a simple location shift. B. Mood scores are high at the tails. C. Ansari–Bradley scores are high near the centre. D. Centre assumptions can be ignored in every scale test.\",\n   \"options\": [\n    \"A, B and C only\",\n    \"A and D only\",\n    \"B and D only\",\n    \"A, B, C and D\"\n   ],\n   \"answer\": \"A\",\n   \"explanation\": \"A, B and C are correct. D is false: scale-test interpretation depends on the procedure's centring and shape assumptions.\",\n   \"statements\": [\n    \"They target dispersion rather than a simple location shift.\",\n    \"Mood scores are high at the tails.\",\n    \"Ansari–Bradley scores are high near the centre.\",\n    \"Centre assumptions can be ignored in every scale test.\"\n   ],\n   \"verdicts\": {\n    \"A\": {\n     \"tf\": true,\n     \"why\": \"True: scale alternatives concern spread or variability.\"\n    },\n    \"B\": {\n     \"tf\": true,\n     \"why\": \"True: Mood uses squared distance from the pooled rank centre.\"\n    },\n    \"C\": {\n     \"tf\": true,\n     \"why\": \"True: Ansari–Bradley scores are centre-sensitive.\"\n    },\n    \"D\": {\n     \"tf\": false,\n     \"why\": \"False: centring and symmetry assumptions must be checked.\"\n    }\n   }\n  },\n  {\n   \"id\": \"np-t8-m-18\",\n   \"format\": \"single\",\n   \"diff\": \"hard\",\n   \"topic\": \"nonparam-t8\",\n   \"stem\": \"Two distributions have the same centre but different spread. Which score pattern is more appropriate than ordinary increasing rank scores?\",\n   \"options\": [\n    \"Wilcoxon rank-sum only\",\n    \"A scale score such as Ansari–Bradley or Mood\",\n    \"A paired sign test\",\n    \"A runs test\"\n   ],\n   \"answer\": \"B\",\n   \"explanation\": \"The alternative concerns dispersion, so use a scale-oriented score pattern and verify its centring assumptions.\"\n  },\n  {\n   \"id\": \"np-t8-m-19\",\n   \"format\": \"single\",\n   \"diff\": \"hard\",\n   \"topic\": \"nonparam-t8\",\n   \"stem\": \"Why does a large Wilcoxon rank-sum total not automatically prove a median difference?\",\n   \"options\": [\n    \"Because ranks cannot be added\",\n    \"Because it is a scale test\",\n    \"Because the test compares distributions and a median interpretation needs comparable shapes\",\n    \"Because it requires paired data\"\n   ],\n   \"answer\": \"C\",\n   \"explanation\": \"The rank-sum test compares distributions through pooled ordering. A simple location or median interpretation is strongest when shapes are similar.\"\n  },\n  {\n   \"id\": \"np-t8-m-20\",\n   \"format\": \"single\",\n   \"diff\": \"hard\",\n   \"topic\": \"nonparam-t8\",\n   \"stem\": \"If sample A receives a larger Ansari–Bradley score sum than sample B, under the common-centre scale alternative this is evidence that sample A is:\",\n   \"options\": [\n    \"More likely to be paired\",\n    \"More spread out into the tails\",\n    \"Shifted to larger raw values\",\n    \"More concentrated near the centre\"\n   ],\n   \"answer\": \"D\",\n   \"explanation\": \"Ansari–Bradley scores are largest near the pooled centre, so a larger score sum indicates more concentration for the labelled sample under the test's assumptions.\"\n  }\n ]\n}"

